    func put(_ k: UInt64, _ v: V) { lock.lock(); values[k] = v; lock.unlock() }
    func get(_ k: UInt64) -> V? { lock.lock(); defer { lock.unlock() }; return values[k] }
    @discardableResult func remove(_ k: UInt64) -> V? { lock.lock(); defer { lock.unlock() }; return values.removeValue(forKey: k) }
}

/// The tasks of asynchronous calls and streams, by their call, which Go
/// cancels.
final class _MygoTasks: @unchecked Sendable {
    private let lock = NSLock()
    private var tasks: [UInt64: Task<Void, Never>] = [:]
    private var done: Set<UInt64> = []
    private var canceled: Set<UInt64> = []

    func put(_ call: UInt64, _ t: Task<Void, Never>) {
        lock.lock()
        defer { lock.unlock() }
        if done.remove(call) != nil { return }
        if canceled.remove(call) != nil { t.cancel() }
        tasks[call] = t
    }

    func finish(_ call: UInt64) {
        lock.lock()
        defer { lock.unlock() }
        if tasks.removeValue(forKey: call) == nil { done.insert(call) }
        canceled.remove(call)
    }

    func cancel(_ call: UInt64) {
        lock.lock()
        let t = tasks.removeValue(forKey: call)
        if t == nil, done.remove(call) == nil { canceled.insert(call) }
        lock.unlock()
        t?.cancel()
    }
}

let _goletTasks = _MygoTasks()
let _goletDemands = _MygoTable<AsyncStream<Void>.Continuation>()
let _goletConts = _MygoTable<CheckedContinuation<_MygoBlock, Never>>()

/// A block Go answered with, for a continuation.
struct _MygoBlock: @unchecked Sendable {
    let p: UnsafeMutableRawPointer?
}

private let _goletIDLock = NSLock()
nonisolated(unsafe) private var _goletLastID: UInt64 = 0
/// The module's index, from Go, in the high bits of every id, which makes
/// the ids of continuations unique among modules.
nonisolated(unsafe) var _goletIDBase: UInt64 = 0

func _goletNextID() -> UInt64 {
    _goletIDLock.lock()
    defer { _goletIDLock.unlock() }
    _goletLastID += 1
    return _goletIDBase | _goletLastID
}

func _goletFinish(_ call: UInt64, _ body: (inout _MygoWriter) async throws -> Void) async {
    var w = _MygoWriter()
    var status: Int64 = 0
    do {
        try await body(&w)
    } catch {
        w.reset()
        _goletWriteError(&w, error)
        status = 1
    }
    _goletTasks.finish(call)
    _goletSend(_goletKindResult, call, status, w)
    w.free()
}

func _goletTask(_ call: UInt64, _ body: @escaping (inout _MygoWriter) async throws -> Void) {
    _goletTasks.put(call, Task { await _goletFinish(call, body) })
}

func _goletTaskMain(_ call: UInt64, _ body: @escaping @MainActor (inout _MygoWriter) async throws -> Void) {
    _goletTasks.put(call, Task { @MainActor in await _goletFinish(call, body) })
}

func _goletIterate<S: AsyncSequence & Sendable>(_ call: UInt64, _ s: S, _ demand: AsyncStream<Void>, _ enc: (inout _MygoWriter, S.Element) -> Void) async {
    var it = s.makeAsyncIterator()
    var lent: S.Element? = nil
    var w = _MygoWriter()
    for await _ in demand {
        // Go is done with what the previous value lent.
        (lent as? NativeBuffer)?.recycle()
        lent = nil
        w.reset()
        do {
            guard let v = try await it.next() else {
                _goletSend(_goletKindItem, call, 3, nil)
                break
            }
            lent = v
            enc(&w, v)
            _goletSend(_goletKindItem, call, 0, w)
        } catch {
            _goletWriteError(&w, error)
            _goletSend(_goletKindItem, call, 1, w)
            break
        }
    }
    w.free()
    withExtendedLifetime(lent) {}
    _goletDemands.remove(call)
    _goletTasks.finish(call)
}

func _goletDemand(_ call: UInt64) -> AsyncStream<Void> {
    var cont: AsyncStream<Void>.Continuation!
    let demand = AsyncStream<Void>(bufferingPolicy: .unbounded) { cont = $0 }
    _goletDemands.put(call, cont)
    return demand
}

func _goletStream<S: AsyncSequence & Sendable>(_ call: UInt64, _ make: @escaping () -> S, _ enc: @escaping (inout _MygoWriter, S.Element) -> Void) {
    let demand = _goletDemand(call)
    _goletTasks.put(call, Task { await _goletIterate(call, make(), demand, enc) })
}

func _goletStreamMain<S: AsyncSequence & Sendable>(_ call: UInt64, _ make: @escaping @MainActor () -> S, _ enc: @escaping (inout _MygoWriter, S.Element) -> Void) {
    let demand = _goletDemand(call)
    _goletTasks.put(call, Task { @MainActor in await _goletIterate(call, make(), demand, enc) })
}

/// A Go function the implementation calls: a notification, or a question
/// Go answers at once. Both take the writer of the arguments, and free it.
final class _MygoGoFunc: @unchecked Sendable {
    let id: UInt64
    init(_ id: UInt64) { self.id = id }
    deinit { if id != 0 { _goletSend(_goletKindRelease, id, 0, nil) } }

    func notify(_ w: _MygoWriter) {
        if id != 0 { _goletSend(_goletKindNotify, id, 0, w) }
        w.free()
    }

    func ask<R>(_ w: _MygoWriter, _ read: (inout _MygoReader) throws -> R) throws -> R {
        defer { w.free() }
        guard id != 0 else { throw NativeError.closed }
        return try _goletAnswer(_goletSend(_goletKindAsk, id, 0, w), read)
    }
}

/// Calls the method of a value of Go's that w names, with the arguments
/// after it, and frees w.
func _goletInvoke<R>(_ id: UInt64, _ w: _MygoWriter, _ read: (inout _MygoReader) throws -> R) throws -> R {
    defer { w.free() }
    return try _goletAnswer(_goletSend(_goletKindInvoke, id, 0, w), read)
}

func _goletInvokeAsync<R>(_ id: UInt64, _ w: _MygoWriter, _ read: (inout _MygoReader) throws -> R) async throws -> R {
    let cont = _goletNextID()
    let b = await withTaskCancellationHandler {
        await withCheckedContinuation { (c: CheckedContinuation<_MygoBlock, Never>) in
            _goletConts.put(cont, c)
            _goletSend(_goletKindInvokeAsync, id, Int64(bitPattern: cont), w)
            w.free()
        }
    } onCancel: {
        _goletSend(_goletKindCancel, cont, 0, nil)
    }
    return try _goletAnswer(b.p, read)
}
